@pytest.mark.parametrize("merged_scenario_data", indirect=True, ids=_idfn_scenario)
def test_get_project_workflow_metrics_pagination_token_roundtrip(
    api_client,
    swagger_validator: SwaggerSchemaValidator,
    endpoint_test_data: List[Dict[str, Any]],
    merged_scenario_data: Dict[str, Any],
):
    """
    If the first response returns next_page_token, optionally attempt a second page request
    using that token to validate pagination schema adherence.
    - This test will no-op if the response does not include a next_page_token field or is null.
    """
    for scenario in endpoint_test_data:
        tmp = dict(merged_scenario_data or {})
        tmp.update(scenario or {})

        project_slug = tmp.get("project-slug")
        if not project_slug:
            pytest.skip("project-slug not provided in config_test_data or scenario data")

        endpoint_path = _build_endpoint_path(project_slug)
        params = _extract_query_params(tmp)

        first_resp = api_client.get(endpoint_path, params=params if params else None)

        # Validate first response strictly
        valid1, result1 = _validate_response_against_spec(swagger_validator, first_resp, ENDPOINT_TEMPLATE, HTTP_METHOD)
        assert valid1, f"Schema validation failed (first page): {result1}"

        # If not HTTP 200 or content is not JSON, skip pagination follow-up
        if first_resp.status_code != 200:
            continue

        ctype = first_resp.headers.get("Content-Type", "")
        if "json" not in ctype.lower():
            continue

        try:
            body = first_resp.json()
        except Exception:
            continue

        next_token = body.get("next_page_token")
        if not next_token:
            # No pagination to test further
            continue

        # Second page request with next_page_token from prior response.
        page2_params = dict(params or {})
        page2_params["page-token"] = next_token

        second_resp = api_client.get(endpoint_path, params=page2_params)
        valid2, result2 = _validate_response_against_spec(swagger_validator, second_resp, ENDPOINT_TEMPLATE, HTTP_METHOD)
        assert valid2, f"Schema validation failed (second page): {result2}"


